const items = $input.all();

function clean(value) {
  return String(value ?? '').trim();
}

function formatTimeline(timeline) {
  return (Array.isArray(timeline) ? timeline : [])
    .slice(-20)
    .map((entry) => {
      const direction = clean(entry.direction).toLowerCase() || 'message';
      const author = clean(entry.sender_name ?? entry.author ?? (direction === 'outbound' ? 'Agente' : 'Cliente')) || (direction === 'outbound' ? 'Agente' : 'Cliente');
      const body = clean(entry.body);
      return '- ' + author + ' (' + direction + '): ' + body;
    })
    .join('\n');
}

return items.map((item) => {
  const payload = item.json ?? {};
  const company = payload.company ?? {};
  const agent = payload.agent ?? {};
  const conversation = payload.conversation ?? {};
  const message = payload.message ?? {};
  const timeline = Array.isArray(payload.timeline) ? payload.timeline : [];
  const knowledgeBase = clean(payload.knowledge_base ?? '');
  const companyId = payload.company_id ?? company.id ?? 'unknown';
  const conversationId = payload.conversation_id ?? conversation.id ?? 'unknown';
  const assistantName = clean(agent.name ?? 'Stark') || 'Stark';
  const companyName = clean(company.trade_name ?? company.name ?? payload.company_name ?? 'a empresa') || 'a empresa';
  const messageBody = clean(message.body ?? payload.request?.message ?? '');
  const recentContext = formatTimeline(timeline);
  const sessionKey = 'squid-hybrid:' + companyId + ':' + conversationId;

  const systemMessage = [
    'Você é Stark, assistente virtual técnico de uma software house para hospitais, clínicas, laboratórios e centros de diagnóstico.',
    'Responda sempre em português do Brasil.',
    'Tom: natural, acolhedor, objetivo e profissional, sem soar robotizado.',
    'Se a mensagem for apenas saudação, responda de forma curta e humana.',
    'Se houver pergunta, dúvida ou problema operacional, use a base técnica e o histórico para responder diretamente com passos claros.',
    'Se a base não for suficiente, defina handoff_to_human como true e entregue um resumo curto da conversa.',
    'Nunca use a expressão "dúvida específica".',
    'Retorne somente JSON válido com as chaves: reply, handoff_to_human, assistant_name, confidence, category, notes, summary, handoff_message.'
  ].join('\n');

  const chatInput = [
    'Empresa: ' + companyName,
    'Agente: ' + assistantName,
    'Session key: ' + sessionKey,
    '',
    'Pergunta do cliente:',
    messageBody || '(vazio)',
    '',
    'Histórico recente da conversa:',
    recentContext || 'Sem histórico adicional.',
    '',
    'Base técnica completa do cliente:',
    knowledgeBase || 'Base técnica vazia.',
    '',
    'Instrução: se houver conteúdo na base que responda a pergunta, responda diretamente com o procedimento.',
    'Instrução: se não houver base suficiente, faça handoff com um resumo curto.',
    'Instrução: se a mensagem for apenas saudação, cumprimente de forma breve e convide para explicar o pedido.'
  ].join('\n');

  return {
    json: {
      ...payload,
      company,
      agent,
      conversation,
      assistant_name: assistantName,
      knowledge_base: knowledgeBase,
      recent_context: recentContext,
      session_key: sessionKey,
      systemMessage,
      chatInput,
      replied_to_message_id: Number(payload.message_id ?? payload.replied_to_message_id ?? 0) || null,
      external_message_id: String(payload.external_message_id ?? ('virtual-agent-response:' + (payload.message_id ?? Date.now())))
    }
  };
});

const items = $input.all();

function text(value) {
  return String(value ?? '').trim();
}

function extractJsonCandidate(value) {
  if (typeof value !== 'string') {
    return null;
  }

  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }

  const fencePrefix = new RegExp('^```(?:json)?\\s*', 'i');
  const fenceSuffix = new RegExp('\\s*```$', 'i');
  const prefix = new RegExp('^json\\s*', 'i');

  const cleaned = trimmed
    .replace(fencePrefix, '')
    .replace(fenceSuffix, '')
    .replace(prefix, '')
    .trim();

  if (cleaned.startsWith('{') && cleaned.endsWith('}')) {
    return cleaned;
  }

  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    return cleaned.slice(firstBrace, lastBrace + 1);
  }

  return null;
}

function parseMaybeJson(value) {
  if (value && typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string') {
    return null;
  }

  const candidate = extractJsonCandidate(value);
  if (!candidate) {
    return null;
  }

  try {
    return JSON.parse(candidate);
  } catch {
    return null;
  }
}

function buildSummary(payload) {
  const messageBody = text(payload.message?.body ?? payload.request?.message ?? payload.chatInput);
  const recent = text(payload.recent_context);
  const parts = [];
  if (messageBody) parts.push('Cliente perguntou: ' + messageBody);
  if (recent) parts.push('Histórico recente: ' + recent);
  return parts.join('. ');
}

function unwrapPayload(payload) {
  if (payload && typeof payload === 'object' && payload.json && typeof payload.json === 'object') {
    return payload.json;
  }

  return payload;
}

return items.map((item) => {
  const payload = unwrapPayload(item.json ?? {});
  const assistantName = text(payload.assistant_name ?? payload.agent?.name ?? 'Stark') || 'Stark';
  const raw = payload.output ?? payload.text ?? payload.response ?? payload.answer ?? payload.result ?? payload.content ?? payload.reply ?? '';
  const parsed = parseMaybeJson(raw) ?? parseMaybeJson(payload.reply) ?? parseMaybeJson(payload.final_reply) ?? parseMaybeJson(payload.output) ?? {};
  const reply = text(parsed.reply ?? parsed.message ?? parsed.output ?? parsed.text ?? parsed.answer ?? payload.final_reply ?? payload.reply ?? raw);
  const handoffToHuman = Boolean(parsed.handoff_to_human ?? payload.handoff_to_human ?? false);
  const confidence = Number(parsed.confidence ?? payload.confidence ?? (handoffToHuman ? 0 : 0.9));
  const category = text(parsed.category ?? payload.category ?? (handoffToHuman ? 'handoff' : 'suporte')) || 'suporte';
  const notes = text(parsed.notes ?? payload.notes ?? (handoffToHuman ? 'Sem base suficiente para responder com segurança.' : 'Resposta baseada na base técnica do cliente.'));
  const summary = text(parsed.summary ?? payload.summary ?? buildSummary(payload));
  const handoffMessage = text(parsed.handoff_message ?? payload.handoff_message ?? 'Vou encaminhar seu atendimento para a equipe dar continuidade.') || 'Vou encaminhar seu atendimento para a equipe dar continuidade.';
  const externalMessageId = text(parsed.external_message_id ?? payload.external_message_id ?? ('virtual-agent-response:' + (payload.replied_to_message_id ?? payload.message_id ?? Date.now())));

  return {
    json: {
      ...payload,
      company_id: payload.company_id ?? payload.company?.id ?? null,
      conversation_id: payload.conversation_id ?? null,
      replied_to_message_id: Number(payload.replied_to_message_id ?? payload.message_id ?? 0) || null,
      external_message_id: externalMessageId,
      reply: reply || handoffMessage,
      handoff_to_human: handoffToHuman,
      assistant_name: assistantName,
      confidence,
      category,
      notes,
      summary,
      handoff_message: handoffMessage,
    },
  };
});
